CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,category VARCHAR(80) NOT NULL,description TEXT,cover_image VARCHAR(255),featured TINYINT(1) DEFAULT 0,status ENUM('draft','published') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE posts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,slug VARCHAR(210) NOT NULL UNIQUE,excerpt TEXT,body LONGTEXT,status ENUM('draft','published') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE testimonials (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_name VARCHAR(160) NOT NULL,project_name VARCHAR(180),quote TEXT NOT NULL,active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inquiries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40),project_type VARCHAR(80),budget VARCHAR(80),timeline VARCHAR(120),message TEXT NOT NULL,ip_address VARCHAR(45),status ENUM('new','contacted','closed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
